# Build candidate position by position (0-indexed), length 122
t='.(((.(((...(((.(((...))).(((....))).)))...(((.(((....))).(((...))).)))...(((.(((....))).(((...))).)))...))).(((...))).))).'
n=len(t)
seq=['?']*n
pairs={}
stack=[]
for i,c in enumerate(t):
    if c=='(':
        stack.append(i)
    elif c==')':
        j=stack.pop()
        pairs[j]=i
        pairs[i]=j
# assign pairs: G-C for stem pairs, but hairpin-closing pair (innermost) as C-G
# find hairpin-closing pairs: a pair (i,j) with no nested pairs
def is_hairpin_close(i):
    j=pairs[i]
    # no pair (k,l) with i<k<l<j
    for k in range(i+1,j):
        if k in pairs and pairs[k]<j and pairs[k]>k:
            return False
    return True
for i in range(n):
    if i in pairs and i<pairs[i]:
        j=pairs[i]
        if is_hairpin_close(i):
            seq[i]='C'; seq[j]='G'
        else:
            seq[i]='G'; seq[j]='C'
# unpaired
for i,c in enumerate(t):
    if c=='.':
        seq[i]='A'
# now place loop caps
# hairpin loops: triloops -> GAA, tetraloops -> GAAA
# find loops
for i in range(n):
    if i in pairs and i<pairs[i] and is_hairpin_close(i):
        j=pairs[i]
        loop=[k for k in range(i+1,j)]
        if len(loop)==3:
            for k,m in zip(loop,'GAA'):
                seq[k]=m
        elif len(loop)==4:
            for k,m in zip(loop,'GAAA'):
                seq[k]=m
s=''.join(seq)
print(s)
print('len',len(s))
print('matches target len', len(s)==len(t))
